def inverse(record):
    v = int(record['stored'][0])
    major = v // 10**12
    minor = (v // 10**8) % 10**4
    build = (v // 10**4) % 10**4
    revision = v % 10**4
    return f"{major}.{minor}.{build}.{revision}"

